def findWords(board: List[List[str]], words: List[str]) -> List[str]:
    R = len(board)
    C = len(board[0])

    def search(r, c, word, idx, visited):
        if idx == len(word):
            return True
        if r < 0 or r >= R or c < 0 or c >= C or visited[r][c] or board[r][c] != word[idx]:
            return False
        visited[r][c] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if search(r + dr, c + dc, word, idx + 1, visited):
                visited[r][c] = False
                return True
        visited[r][c] = False
        return False

    ans = []
    for w in words:
        found = False
        for r in range(R):
            if found:
                break
            for c in range(C):
                if board[r][c] == w[0]:
                    visited = [[False]*C for _ in range(R)]
                    if search(r, c, w, 0, visited):
                        ans.append(w)
                        found = True
                        break
    return ans

