        self.children = {}
        self.word = None

class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        root = TrieNode()
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
            node.word = word

        rows, cols = len(board), len(board[0])
        result = []

        def dfs(row, col, parent_node):
            char = board[row][col]
            current_node = parent_node.children[char]

            if current_node.word:
                result.append(current_node.word)
                current_node.word = None

            board[row][col] = '#'
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                next_row, next_col = row + dr, col + dc
                if 0 <= next_row < rows and 0 <= next_col < cols:
                    if board[next_row][next_col] in current_node.children:
                        dfs(next_row, next_col, current_node)
            board[row][col] = char

            if not current_node.children:
                parent_node.children.pop(char)

        for r in range(rows):
            for c in range(cols):
                if board[r][c] in root.children:
                    dfs(r, c, root)

        return result

